function startAuto() {
  stopAuto();
  const sec = Math.max(5, (CFG && CFG.market && CFG.market.refresh_sec) || 10);
  autoTimer = setInterval(refreshQuotes, sec * 1000);
}
function stopAuto() { if (autoTimer) { clearInterval(autoTimer); autoTimer = null; } }

/* config.js 是否比库内配置新/更完整 → 判定「未同步」。
   两个信号任一命中即算旧：① meta.generated 晚于 cfgSyncedAt；② config.js 某目标有 governance/ocfd2y 而库内同代码缺（防无 meta 时间戳时漏判）。 */
function configStale() {
  if (!CFG_FROM_JS) return false;
  // 库里压根没有来源/同步记录，但当前 CFG 来自库（非首次导入）→ 视为可能旧（仅在确有差异时提示，见下）
  const dbCfg = (function () { try { const r = q("SELECT v FROM setting WHERE k='cfg'"); return r.length ? JSON.parse(r[0].v) : null; } catch (e) { return null; } })();
  // 首次导入（库内 cfg == config.js）无需提示
  if (!dbCfg) return false;
  // 信号②：逐目标比较关键字段，config.js 有而库内缺
  const dbBy = {}; (dbCfg.targets || []).forEach(t => { dbBy[t.code] = t; });
  for (const t of (CFG_FROM_JS.targets || [])) {
    const d = dbBy[t.code];
    if (!d) continue;
    if ((t.governance && !d.governance) ||
        ((Array.isArray(t.ocfd2y) || typeof t.ocfd2y === 'number') && !d.ocfd2y) ||
        ((Array.isArray(t.payout2y) || typeof t.payout2y === 'number') && !d.payout2y)) {
      return true;
    }
  }
  // 信号①：meta.generated 晚于 cfgSyncedAt
  const jsGen = CFG_FROM_JS.meta && CFG_FROM_JS.meta.generated;
  const syncedAt = cfgSyncedAt();
  if (jsGen && syncedAt) {
    const genMs = Date.parse(String(jsGen).replace(' ', 'T'));
    const syncMs = Date.parse(syncedAt);
    if (isFinite(genMs) && isFinite(syncMs) && genMs > syncMs + 60000) return true;
  }
  return false;
}
function refreshCfgBanner() {
  const b = document.getElementById('cfgBanner');
  if (!b) return;
  if (configStale()) {
    document.getElementById('cfgBannerText').textContent = 'config.js 已有更新（含治理/时序等字段），但库内配置较旧、尚未同步——请点右侧按钮同步，否则面板仍按旧配置计算。';
    b.classList.add('show');
  } else {
    b.classList.remove('show');
  }
}

