/* ---------- 19. config.js 比库内新 → 顶部提示 + 一键同步 ---------- */
console.log('\n--- 配置未同步检测 ---');
const dC = new SQL.Database(); dC.exec(SCHEMA); P._setDb(dC); P._seedInto(dC); P._readState();
// 注入「旧版」库内 cfg：targets 无 governance/ocfd2y（模拟本次真实踩坑）
const oldCfg = JSON.parse(JSON.stringify(sandbox.window.PANEL_CONFIG));
oldCfg.targets.forEach(t => { delete t.governance; delete t.ocfd2y; });
dC.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfg', JSON.stringify(oldCfg)]);
P._setDb(dC); P._readState(); // 让面板重新从库加载（模拟旧库）
ok(P.configStale() === true, '#19 库内 cfg 缺 governance、config.js 有 → configStale=true');
// doSyncCfg 同步后 → 不再 stale
P.doSyncCfg && (sandbox.confirm = () => true);
P.doSyncCfg();
P._readState();
ok(P.configStale() === false, '#19 同步 config.js 后 → configStale=false');
// 库内 cfg 与 config.js 一致时不提示
ok(P.configStale() === false, '#19 一致时无提示');

P.applyConfig(sandbox.window.PANEL_CONFIG);
P._setDb(dbOld); P._readState();

console.log('\n' + (fail ? '有 ' + fail + ' 项失败' : '全部通过'));
process.exit(fail ? 1 : 0);

